/**
 * Shell completion script generation for the `arcturn` CLI.
 *
 * `arcturn completions <bash|zsh|fish>` prints a self-contained script for the
 * requested shell. Everything the scripts know about — flags, their value
 * hints, enum choices, and subcommands — comes from a single declarative
 * table, {@link DEFAULT_COMPLETION_SPEC}. When a flag is added to `args.ts`,
 * updating that table (and nothing else) keeps completions in sync.
 *
 * The scripts are plain text generated by string templates; no shell is
 * invoked at generation time. `--model` is the one place a script calls back
 * into `arcturn` at completion time (`arcturn --list-models`), since the model
 * catalog can grow via extensions and would otherwise drift from a static
 * list. That call is guarded in every shell so a slow or failing `arcturn`
 * degrades to "no suggestions" rather than hanging or erroring the shell.
 */

/** A shell `arcturn completions` knows how to target. */
export type CompletionShell = "bash" | "zsh" | "fish";

/** Every supported shell, in the order they are documented. */
export const COMPLETION_SHELLS: readonly CompletionShell[] = ["bash", "zsh", "fish"];

/** Narrow an arbitrary string to a {@link CompletionShell}. */
export function isCompletionShell(value: string): value is CompletionShell {
  return (COMPLETION_SHELLS as readonly string[]).includes(value);
}

/**
 * Thrown by {@link generateCompletions} when asked for a shell it does not
 * recognise.
 *
 * Kept as a distinct class (rather than a plain `Error`) so callers such as
 * `main.ts` can match on `instanceof` and turn it into the same tidy
 * usage-error exit path used for a bad `--permission-mode` or `--output-format`.
 */
export class UnknownCompletionShellError extends Error {
  /** The value that was rejected. */
  readonly shell: string;

  constructor(shell: string) {
    super(`Unknown completion shell "${shell}". Expected one of: ${COMPLETION_SHELLS.join(", ")}.`);
    this.name = "UnknownCompletionShellError";
    this.shell = shell;
  }
}

/** What kind of value a flag's argument holds, so a script knows how to complete it. */
export type CompletionValueHint = "model" | "path" | "mode" | "format" | "session" | "number";

/** One flag `arcturn` accepts, as far as completion needs to know. */
export interface CompletionFlag {
  /** Long form, e.g. `"--model"`. */
  readonly long: string;
  /** Short alias, e.g. `"-m"`, when one exists. */
  readonly short?: string;
  /** Whether the flag takes a value (`--model x`) or is a bare switch. */
  readonly takesValue: boolean;
  /** What the value represents, when {@link takesValue} is true. */
  readonly valueHint?: CompletionValueHint;
  /** Fixed set of legal values, when the value is an enum (e.g. permission modes). */
  readonly enumValues?: readonly string[];
  /** One-line description shown by shells that support it (zsh, fish). */
  readonly description: string;
}

/** A positional sub-command, optionally with its own fixed set of child words. */
export interface CompletionSubcommand {
  /** The word itself, e.g. `"completions"`. */
  readonly name: string;
  /** One-line description shown by shells that support it. */
  readonly description: string;
  /** Fixed words that can follow this subcommand (e.g. `completions`' shells). */
  readonly children?: readonly CompletionSubcommand[];
}

/** Everything a completion script needs: the program name, its flags, and its subcommands. */
export interface CompletionSpec {
  /** Executable name completions are registered for (`arcturn`). */
  readonly program: string;
  /** Every flag, in help-text order. */
  readonly flags: readonly CompletionFlag[];
  /** Every top-level positional command. */
  readonly subcommands: readonly CompletionSubcommand[];
}

