/**
 * Generate a completion script for one shell.
 *
 * @param shell - `"bash"`, `"zsh"` or `"fish"`. Any other value throws
 *   {@link UnknownCompletionShellError} rather than returning an empty or
 *   partial script, so a typo surfaces immediately.
 * @param spec - Flag/subcommand table to render; defaults to
 *   {@link DEFAULT_COMPLETION_SPEC}.
 * @returns The full script, ready to write to a file or `eval`.
 */
export function generateCompletions(
  shell: string,
  spec: CompletionSpec = DEFAULT_COMPLETION_SPEC,
): string {
  if (!isCompletionShell(shell)) {
    throw new UnknownCompletionShellError(shell);
  }
  switch (shell) {
    case "bash":
      return generateBashCompletions(spec);
    case "zsh":
      return generateZshCompletions(spec);
    case "fish":
      return generateFishCompletions(spec);
  }
}

/** Escape a string for embedding inside a zsh single-quoted literal. */
function escapeZshSingleQuoted(value: string): string {
  return value.replace(/'/g, "'\\''");
}

/** Escape a string for embedding inside a fish single-quoted literal. */
function escapeFishSingleQuoted(value: string): string {
  return value.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
}

/** Long and short forms of a flag, flattened into one list. */
function flagWords(flag: CompletionFlag): string[] {
  return flag.short ? [flag.long, flag.short] : [flag.long];
}

/**
 * The POSIX shell body shared by the bash and zsh scripts for resolving
 * `--model` candidates.
 *
 * Wrapped in `timeout` when available so a hung or slow `arcturn` (e.g. waiting
 * on a network-backed extension) cannot stall tab completion; when `timeout`
 * is not on `$PATH`, the call still runs but errors and empty output are
 * swallowed, so the worst case is no suggestions rather than a shell error.
 */
function posixListModelsFunction(program: string, functionName: string): string {
  return [
    `${functionName}() {`,
    `  if command -v timeout >/dev/null 2>&1; then`,
    `    timeout 0.3 ${program} --list-models 2>/dev/null | awk 'NR>1{print $1}'`,
    `  else`,
    `    ${program} --list-models 2>/dev/null | awk 'NR>1{print $1}'`,
    `  fi`,
    `}`,
  ].join("\n");
}

/** Render the bash completion script. */
function generateBashCompletions(spec: CompletionSpec): string {
  const program = spec.program;
  const funcName = `_${program}_completions`;
  const listModelsFn = `_${program}_list_models`;

  const allFlagWords = spec.flags.flatMap(flagWords).join(" ");
  const topLevelWords = spec.subcommands.map((s) => s.name).join(" ");

  const cases: string[] = [];

  for (const flag of spec.flags) {
    if (!flag.takesValue) continue;
    const pattern = flagWords(flag).join("|");
    if (flag.enumValues && flag.enumValues.length > 0) {
      cases.push(
        [
          `    ${pattern})`,
          `      COMPREPLY=( $(compgen -W "${flag.enumValues.join(" ")}" -- "$cur") )`,
          `      return 0`,
          `      ;;`,
        ].join("\n"),
      );
    } else if (flag.valueHint === "model") {
      cases.push(
        [
          `    ${pattern})`,
          `      local models`,
          `      models="$(${listModelsFn})"`,
          `      if [ -n "$models" ]; then`,
          `        COMPREPLY=( $(compgen -W "$models" -- "$cur") )`,
          `      fi`,
          `      return 0`,
          `      ;;`,
        ].join("\n"),
      );
    } else if (flag.valueHint === "path") {
      cases.push(
        [
          `    ${pattern})`,
          `      COMPREPLY=( $(compgen -f -- "$cur") )`,
          `      return 0`,
          `      ;;`,
        ].join("\n"),
      );
    }
  }

  for (const sub of spec.subcommands) {
    if (!sub.children || sub.children.length === 0) continue;
    const childWords = sub.children.map((c) => c.name).join(" ");
    cases.push(
      [
        `    ${sub.name})`,
        `      COMPREPLY=( $(compgen -W "${childWords}" -- "$cur") )`,
        `      return 0`,
        `      ;;`,
      ].join("\n"),
    );
  }

  return `# bash completion for ${program}
#
# Generated by \`${program} completions bash\`. Load it in your shell, e.g.:
#   ${program} completions bash > /usr/local/etc/bash_completion.d/${program}
# or source it directly from ~/.bashrc:
#   source <(${program} completions bash)

${posixListModelsFunction(program, listModelsFn)}

${funcName}() {
  local cur prev
  COMPREPLY=()
  cur="\${COMP_WORDS[COMP_CWORD]}"
  prev="\${COMP_WORDS[COMP_CWORD-1]}"

  case "$prev" in
${cases.join("\n")}
  esac

  if [[ "$cur" == -* ]]; then
    COMPREPLY=( $(compgen -W "${allFlagWords}" -- "$cur") )
  else
    COMPREPLY=( $(compgen -W "${topLevelWords}" -- "$cur") )
  fi
}

complete -F ${funcName} ${program}
`;
}

/** Zsh `_arguments` value-spec for one flag (empty string for bare switches). */
function zshArgSpec(flag: CompletionFlag): string {
  if (!flag.takesValue) return "";
  const hint = flag.valueHint ?? "value";
  if (flag.enumValues && flag.enumValues.length > 0) {
    return `:${hint}:(${flag.enumValues.join(" ")})`;
  }
  if (flag.valueHint === "model") {
    return `:model:->models`;
  }
  if (flag.valueHint === "path") {
    return `:path:_files -/`;
  }
  return `:${hint}:`;
}

/** Render the zsh completion script. */
function generateZshCompletions(spec: CompletionSpec): string {
  const program = spec.program;
  const funcName = `_${program}`;
  const listModelsFn = `_${program}_list_models`;

  const optionLines: string[] = [];
  for (const flag of spec.flags) {
    const desc = escapeZshSingleQuoted(flag.description);
    const argSpec = zshArgSpec(flag);
    optionLines.push(`    '${flag.long}[${desc}]${argSpec}'`);
    if (flag.short) {
      optionLines.push(`    '${flag.short}[${desc}]${argSpec}'`);
    }
  }

  const topLevelValues = spec.subcommands
    .map((s) => `'${s.name}[${escapeZshSingleQuoted(s.description)}]'`)
    .join(" ");

  // One arm per subcommand that has a fixed child list, so adding or removing
  // a command in the spec is the whole edit.
  const childArms = spec.subcommands
    .filter((sub) => sub.children && sub.children.length > 0)
    .map((sub) => {
      const values = (sub.children ?? [])
        .map((child) => `'${child.name}[${escapeZshSingleQuoted(child.description)}]'`)
        .join(" ");
      return [
        `        ${sub.name})`,
        `          _values '${sub.name} argument' ${values}`,
        `          ;;`,
      ].join("\n");
    })
    .join("\n");

  return `#compdef ${program}
#
# Generated by \`${program} completions zsh\`. Load it in your shell, e.g.:
#   ${program} completions zsh > "\${fpath[1]}/_${program}"
# or source it directly from ~/.zshrc:
#   source <(${program} completions zsh)

${posixListModelsFunction(program, listModelsFn)}

${funcName}() {
  local context state state_descr line
  typeset -A opt_args
  local -a models

  _arguments -C \\
${optionLines.join(" \\\n")} \\
    '1: :->cmds' \\
    '*:: :->args'

  case "$state" in
    models)
      models=(\${(f)"$(${listModelsFn})"})
      _describe -t models 'model' models
      ;;
    cmds)
      _values 'command' ${topLevelValues}
      ;;
    args)
      case "\${line[1]}" in
${childArms}
      esac
      ;;
  esac
}

${funcName} "$@"
`;
}

/** Render the fish completion script. */
function generateFishCompletions(spec: CompletionSpec): string {
  const program = spec.program;
  const listModelsFn = `__${program}_list_models`;

  const lines: string[] = [];
  lines.push(`# fish completion for ${program}`);
  lines.push(`#`);
  lines.push(`# Generated by \`${program} completions fish\`. Save it as:`);
  lines.push(`#   ~/.config/fish/completions/${program}.fish`);
  lines.push("");
  lines.push(`function ${listModelsFn}`);
  lines.push(`    if command -v timeout >/dev/null 2>&1`);
  lines.push(`        timeout 0.3 ${program} --list-models 2>/dev/null | awk 'NR>1{print $1}'`);
  lines.push(`    else`);
  lines.push(`        ${program} --list-models 2>/dev/null | awk 'NR>1{print $1}'`);
  lines.push(`    end`);
  lines.push(`end`);
  lines.push("");
  lines.push(`complete -c ${program} -f`);
  lines.push("");

  for (const sub of spec.subcommands) {
    const desc = escapeFishSingleQuoted(sub.description);
    lines.push(`complete -c ${program} -n '__fish_use_subcommand' -a '${sub.name}' -d '${desc}'`);
  }
  lines.push("");

  for (const sub of spec.subcommands) {
    if (!sub.children || sub.children.length === 0) continue;
    const childNames = sub.children.map((c) => c.name).join(" ");
    lines.push(
      `complete -c ${program} -n '__fish_seen_subcommand_from ${sub.name}' -a '${childNames}'`,
    );
  }
  lines.push("");

  for (const flag of spec.flags) {
    const longName = flag.long.replace(/^--/, "");
    const shortPart = flag.short ? ` -s ${flag.short.replace(/^-/, "")}` : "";
    const desc = escapeFishSingleQuoted(flag.description);

    if (!flag.takesValue) {
      lines.push(`complete -c ${program}${shortPart} -l ${longName} -d '${desc}'`);
      continue;
    }
    if (flag.enumValues && flag.enumValues.length > 0) {
      lines.push(
        `complete -c ${program}${shortPart} -l ${longName} -x -a '${flag.enumValues.join(" ")}' -d '${desc}'`,
      );
    } else if (flag.valueHint === "model") {
      lines.push(
        `complete -c ${program}${shortPart} -l ${longName} -x -a '(${listModelsFn})' -d '${desc}'`,
      );
    } else if (flag.valueHint === "path") {
      lines.push(`complete -c ${program}${shortPart} -l ${longName} -r -F -d '${desc}'`);
    } else {
      lines.push(`complete -c ${program}${shortPart} -l ${longName} -x -d '${desc}'`);
    }
  }

  return `${lines.join("\n")}\n`;
}
